/**
 * Every image on the site, in one map.
 *
 * !! EVERY PHOTOGRAPH HERE IS A PLACEHOLDER. They are licensed Unsplash stock,
 * chosen against the imagery rules in the plan (2.4): warm natural light, real
 * workrooms, fabric texture, machines and hands working. Never a headset, an
 * office or a handshake. They show what the site looks like once real work
 * is in it.
 *
 * To swap in the client's own photos: drop the files in /public and change
 * `src` to e.g. "/photos/workroom.jpg". Nothing outside this file changes.
 * Remote hosts need a matching entry in next.config.ts remotePatterns.
 *
 * GRADE is applied to every remote image so stock from different photographers
 * reads as one consistent brand. Drop it when real photos land.
 */

export type Img = {
  src: string;
  alt: string;
  /** Tiny inline JPEG used as the blur-up placeholder. */
  blurDataURL: string;
};

/** Slight desaturation, a touch of lift, softened contrast. */
const GRADE = "sat=-12&bri=4&con=-3";

const u = (id: string, w: number) =>
  `https://images.unsplash.com/${id}?auto=format&fit=crop&q=80&w=${w}&${GRADE}`;

